def parse_bool(s):
    if isinstance(s, bool):
        return s
    t = str(s).strip().lower()
    if t == 'true':
        return True
    if t == 'false':
        return False
    raise SithError('invalid boolean value: %r' % (s,))


def parse_setting(item):
    key, eq, val = item.partition('=')
    key = key.strip()
    if not eq or key not in SETTING_DEFAULTS:
        raise SithError('invalid setting: %r' % item)
    try:
        return key, parse_bool(val)
    except SithError:
        raise SithError('invalid value for setting %s: %r' % (key, val))


def config_path(root):
    return os.path.join(root, CONFIG_DIR, CONFIG_FILE)


def read_project_config(root):
    """The raw project configuration stored under ``root`` (None if absent)."""
    p = config_path(root)
    if not os.path.isfile(p):
        return None
    try:
        with open(p, 'rb') as f:
            data = json.loads(f.read().decode('utf-8'))
    except (OSError, ValueError) as e:
        raise SithError('invalid project configuration %s: %s' % (p, e))
    if not isinstance(data, dict):
        raise SithError('invalid project configuration %s: not an object' % p)
    return data


def _path_list(v):
    if isinstance(v, str):
        v = [v] if v else []
    if not isinstance(v, list):
        return []
    return [x for x in v if isinstance(x, str) and x]


def load_project_config(root):
    """Normalized project configuration for ``root`` (defaults if absent)."""
    cfg = dict(PROJECT_DEFAULTS)
    data = read_project_config(root) if root else None
    if data:
        env = data.get('environment_path', '')
        cfg['environment_path'] = env if isinstance(env, str) else ''
        cfg['sys_path'] = _path_list(data.get('sys_path'))
        cfg['added_sys_path'] = _path_list(data.get('added_sys_path'))
        for k in SETTING_DEFAULTS:
            if k in data:
                try:
                    cfg[k] = parse_bool(data[k])
                except SithError:
                    raise SithError('invalid value for %s in project configuration' % k)
    return cfg


def effective_settings(cfg):
    out = dict(SETTING_DEFAULTS)
    for k in SETTING_DEFAULTS:
        if k in cfg:
            out[k] = cfg[k]
    out.update(_RUN['settings'])
    return out


def load_namespaces(path):
    try:
        with open(path, 'rb') as f:
            data = json.loads(f.read().decode('utf-8'))
    except OSError as e:
        raise SithError('cannot read namespaces file: %s' % e)
    except ValueError as e:
        raise SithError('invalid namespaces file: %s' % e)
    if not isinstance(data, list) or not all(isinstance(ns, dict) for ns in data):
        raise SithError('invalid namespaces file: expected a JSON array of objects')
    for ns in data:
        for k, v in ns.items():
            if not isinstance(v, dict):
                raise SithError('invalid namespaces file: value of %r is not an object' % k)
    return data


