        return None
    if r.returncode != 0:
        return None
    try:
        data = ast.literal_eval(r.stdout.decode('utf-8', errors='replace').strip())
        version = _version_str(data['version'])
        prefix = data['prefix']
        is_venv = prefix != data['base_prefix'] or data['real_prefix'] is not None
        sys_path = [p for p in data['path'] if isinstance(p, str) and p]
    except Exception:
        return None
    exe_dir = os.path.dirname(exe)
    if not is_venv and (_is_venv_dir(os.path.dirname(exe_dir)) or _is_venv_dir(exe_dir)):
        is_venv = True
    return {'executable': exe, 'version': version, 'is_virtualenv': bool(is_venv),
            'prefix': prefix, 'sys_path': sys_path}


def _env_entry(info):
    return {k: info[k] for k in ('executable', 'version', 'is_virtualenv')}


def _sort_envs(envs):
    envs.sort(key=lambda e: e['executable'])
    envs.sort(key=lambda e: _version_key(e['version']), reverse=True)
    return envs


def _collect(cands, key):
    envs = []
    seen = set()
    for exe in cands:
        exe = os.path.abspath(exe)
        k = key(exe)
        if k in seen:
            continue
        info = _probe(exe)
        if info is None:
            continue
        seen.add(k)
        envs.append(info)
    return envs


def env_list():
    cands = []
    if sys.executable:
        cands.append(sys.executable)
    dirs = os.environ.get('PATH', '').split(os.pathsep)
    dirs += ['/usr/local/bin', '/usr/bin', '/bin', '/opt/homebrew/bin']
    for d in dirs:
        if not d or not os.path.isdir(d):
            continue
        try:
            listing = sorted(os.listdir(d))
        except OSError:
            continue
        for fn in listing:
            if _PY_NAME_RE.match(fn):
                cands.append(os.path.join(d, fn))
    envs = _collect(cands, os.path.realpath)
    return _sort_envs([_env_entry(e) for e in envs])


def _venv_python(d):
    for rel in (os.path.join('bin', 'python'), os.path.join('bin', 'python3'),
                os.path.join('Scripts', 'python.exe')):
        p = os.path.join(d, rel)
        if os.path.isfile(p):
            return p
    return None


def _subdirs(d):
    try:
        names = sorted(os.listdir(d))
    except OSError:
        return []
    return [os.path.join(d, n) for n in names if os.path.isdir(os.path.join(d, n))]


def find_virtualenvs(path=None, project=None):
    dirs = []
    if path is not None:
        if not os.path.isdir(path):
            raise SithError('directory not found: %s' % path)
        dirs += _subdirs(path)
    dirs += _subdirs(os.path.join(os.path.expanduser('~'), '.virtualenvs'))
    bases = [os.getcwd()]
    if project:
        bases.append(project_root(os.getcwd(), project))
    for b in bases:
        dirs += [os.path.join(b, '.venv'), os.path.join(b, 'venv')]
    cands = [p for p in (_venv_python(d) for d in dirs) if p]
    envs = _collect(cands, lambda p: os.path.join(os.path.realpath(os.path.dirname(p)),
                                                  os.path.basename(p)))
    return _sort_envs([_env_entry(e) for e in envs if e['is_virtualenv']])


def _default_python(project=None):
    root = os.path.abspath(project) if project else os.getcwd()
    if project and not os.path.isdir(root):
        raise SithError('project directory not found: %s' % project)
    env = load_project_config(root)['environment_path']
    if env:
        return env if os.sep in env or '/' in env else (_which(env) or env)
    exe = _which('python3') or _which('python')
    if exe is None:
        raise SithError('no default python interpreter found')
    return exe


def _which(name):
    import shutil
    return shutil.which(name)


def env_info(executable=None, project=None):
    exe = executable if executable else _default_python(project)
    if executable and os.sep not in exe and '/' not in exe and not os.path.exists(exe):
        exe = _which(exe) or exe
    exe = os.path.abspath(os.path.expanduser(exe))
    if not os.path.exists(exe):
        raise SithError('python executable not found: %s' % executable)
    info = _probe(exe)
    if info is None:
        raise SithError('not a valid python executable: %s' % exe)
    return info


