def _split_paths(s):
    return [p.strip() for p in s.split(',') if p.strip()]


def project_init(d=None, environment=None, sys_path=None, added_sys_path=None,
                 settings=None):
    d = os.path.abspath(d or os.getcwd())
    if not os.path.isdir(d):
        raise SithError('directory not found: %s' % d)
    cfg = {}
    existing = read_project_config(d)
    if existing:
        cfg.update(existing)
    for k, v in PROJECT_DEFAULTS.items():
        if k not in cfg:
            cfg[k] = list(v) if isinstance(v, list) else v
    if environment is not None:
        cfg['environment_path'] = environment
    if sys_path is not None:
        cfg['sys_path'] = _split_paths(sys_path)
    if added_sys_path is not None:
        cfg['added_sys_path'] = _split_paths(added_sys_path)
    for k, v in (settings or {}).items():
        if k == 'smart_sys_path':
            cfg[k] = v
    cdir = os.path.join(d, CONFIG_DIR)
    p = os.path.join(cdir, CONFIG_FILE)
    try:
        os.makedirs(cdir, exist_ok=True)
        with open(p, 'w', encoding='utf-8') as f:
            json.dump(cfg, f, indent=2, sort_keys=True)
            f.write('\n')
    except OSError as e:
        raise SithError('cannot write project configuration: %s' % e)
    out = dict(cfg)
    out['path'] = p
    out['config'] = cfg
    return out


